(()=>{
 const host=document.getElementById('ai-bots-content');if(!host)return;
 const apiBase='/api/admin/ai-bots',esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),q=s=>host.querySelector(s),all=s=>[...host.querySelectorAll(s)];
 const names={dashboard:'대시보드',accounts:'계정 관리',import:'사이그램 · 일괄 등록',templates:'댓글 관리',settings:'자동화 · 선물 설정',activities:'활동 기록'},categories={first:'첫 작품 축하',original:'음원 업로드',solo:'솔로 커버',duet:'듀엣 완성',dubbing:'더빙 완성',general:'일반 응원'},styles={warm:'따뜻하게',polite:'정중하게',cheerful:'밝게'};
 let tab='dashboard',offset=0,search='',recordOffset=0,items=[],selected=new Set(),revision=0,config=null,loading=false,reviewed=[];
 const label=(text,input)=>`<label>${text}${input}</label>`,options=(map,value)=>Object.entries(map).map(([k,v])=>`<option value="${k}" ${k===value?'selected':''}>${v}</option>`).join('');
 const date=t=>new Date(t*1000).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'});
 async function api(path,method='GET',body){const r=await fetch(apiBase+path,{method,credentials:'same-origin',headers:body instanceof Blob?{'content-type':body.type}:body?{'content-type':'application/json'}:{},body:body instanceof Blob?body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw new Error(d.error||'요청에 실패했어요.');return d;}
 const message=text=>{const el=q('[data-bot-status]');if(el)el.textContent=text;};
 function shell(){host.innerHTML=`<header class="card-head"><div><h1>AI 봇 관리</h1><p>공식 AI 응원 계정 · 실제 회원·유료 매출·정산·인기 순위와 분리</p></div><button type="button" class="small-button" data-bot-stop>긴급 중지</button></header><nav class="bot-tabs" aria-label="AI 봇 관리">${Object.entries(names).map(([key,name])=>`<button type="button" class="${tab===key?'primary-button':'small-button'}" data-bot-tab="${key}" aria-pressed="${tab===key}">${name}</button>`).join('')}</nav><p data-bot-status role="status" aria-live="polite"></p><div data-bot-panel></div>`;q('[data-bot-stop]').onclick=()=>action(async()=>{await api('/stop','POST',{});await render();message('전체 자동 활동을 중지했어요. 대기 작업은 보존됩니다.');});all('[data-bot-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.botTab;render();});}
 async function action(fn){if(loading)return;loading=true;try{await fn();}catch(e){message(e.message);}finally{loading=false;}}
 async function render(){shell();const panel=q('[data-bot-panel]');panel.innerHTML='<p>불러오는 중…</p>';try{
  if(tab==='dashboard'){
   const d=await api('/dashboard');panel.innerHTML=`<p class="bot-state">전체 자동 활동: <strong>${d.enabled?'ON':'OFF · 운영 승인 후 시작'}</strong></p><div class="bot-kpis">${[['등록된 AI 계정',d.registered],['활성 계정',d.active],['오늘 AI 댓글',d.comments],['오늘 공식 응원별',d.stars],['대기 작업',d.pending],['실패 작업',d.failed]].map(([l,v])=>`<article class="admin-card"><small>${l}</small><h2>${Number(v)}</h2></article>`).join('')}</div><p>봇은 음원을 재생하거나 분석하지 않습니다. 무료 응원별은 현금가치가 없으며 실제 팬 선물과 별도입니다.</p><button type="button" class="small-button" data-bot-run>예약 시간이 지난 작업 처리</button><p>실제 실행은 전체 ON 설정에서만 가능합니다. 한 번에 최대 15개씩 처리합니다.</p>`;q('[data-bot-run]').onclick=()=>action(async()=>{const r=await api('/run','POST',{});message(r.stopped?'전체 OFF 상태예요.':r.busy?'다른 실행이 처리 중이에요.':`${r.processed}개 처리 · ${r.failed}개 재시도 예정`);});
   const list=await api('/existing-targets');panel.insertAdjacentHTML('beforeend',`<details class="admin-card"><summary>기존 작품에 소량 테스트</summary><p>선택한 공개 작품에 실제 AI 댓글 최대 1개와 무료 응원별을 예약합니다. 기존 작업을 중복 생성하지 않으며 일일 한도와 실제 회원 반응에 따른 생략 조건을 유지합니다.</p><form data-existing-test>${label('대상 작품',`<select name="target" required><option value="">작품 선택</option>${list.targets.map(t=>`<option value="${esc(t.target_type+':'+t.id)}">${esc(t.title)} · ${esc(t.owner_name)} · ${esc(categories[t.category])}</option>`).join('')}</select>`)}<label><input name="confirmed" type="checkbox" required> 실제 공개 작품에 댓글·공식 응원별이 표시되는 테스트에 동의합니다.</label><button class="small-button">선택한 작품 테스트 예약</button></form></details>`);
   q('[data-existing-test]').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;action(async()=>{const [target_type,target_id]=f.elements.target.value.split(':');const r=await api('/test-existing','POST',{target_type,target_id,confirmed:f.elements.confirmed.checked});message('테스트 작업 확인: '+r.jobs.map(j=>j.action+' · '+j.state).join(', ')+' · 위의 예약 작업 처리 버튼으로 실행할 수 있어요.');});};
  }else if(tab==='accounts'){
   const d=await api('/accounts?q='+encodeURIComponent(search)+'&offset='+offset);panel.innerHTML=`<form data-bot-search class="bot-inline">${label('계정 검색',`<input name="search" value="${esc(search)}" placeholder="닉네임 또는 ai_000001">`)}<button class="small-button">검색</button></form><div class="bot-inline"><button class="small-button" data-select-all>현재 목록 전체 선택</button><button class="small-button" data-bulk="true">선택 활성화</button><button class="small-button" data-bulk="false">선택 비활성화</button><span>총 ${d.total}개</span></div><div class="bot-account-grid">${d.accounts.map(b=>`<article class="management-card bot-account"><label class="bot-select"><input type="checkbox" data-bot-id="${b.user_id}"> ${b.user_id}</label><img loading="lazy" decoding="async" src="/media/producer/${b.user_id}?v=${b.image_version}" alt="${esc(b.name)}"><strong>${esc(b.name)} <span class="ai-account-badge">AI</span></strong><small>${b.active?'활성':'비활성'} · ${b.daily_limit}회/일</small><details><summary>계정 수정</summary><form data-edit-bot="${b.user_id}">${label('닉네임',`<input name="name" maxlength="40" value="${esc(b.name)}" required>`)}${label('댓글 말투',`<select name="style">${options(styles,b.style)}</select>`)}${label('이모지',`<input name="emoji" maxlength="12" value="${esc(b.emoji)}">`)}${label('일일 활동 한도',`<input type="number" name="daily_limit" min="0" max="100" value="${b.daily_limit}" required>`)}<label><input name="active" type="checkbox" ${b.active?'checked':''}> 활성화</label><button class="primary-button">저장</button></form>${label('프로필 이미지 교체',`<input type="file" data-image-bot="${b.user_id}" accept="image/jpeg,image/png,image/webp">`)}</details></article>`).join('')}</div><div class="bot-inline"><button class="small-button" data-prev ${offset===0?'disabled':''}>이전</button><span>${offset+1}~${offset+d.accounts.length}</span><button class="small-button" data-next ${d.accounts.length<50?'disabled':''}>다음</button></div>`;
   q('[data-bot-search]').onsubmit=e=>{e.preventDefault();search=e.currentTarget.elements.search.value;offset=0;render();};q('[data-prev]').onclick=()=>{offset=Math.max(0,offset-50);render();};q('[data-next]').onclick=()=>{offset+=50;render();};q('[data-select-all]').onclick=()=>all('[data-bot-id]').forEach(e=>e.checked=true);
   all('[data-bulk]').forEach(b=>b.onclick=()=>action(async()=>{await api('/accounts/bulk','PATCH',{ids:all('[data-bot-id]:checked').map(e=>e.dataset.botId),active:b.dataset.bulk==='true'});await render();message('선택 계정 설정을 저장했어요.');}));
   all('[data-edit-bot]').forEach(form=>form.onsubmit=e=>{e.preventDefault();action(async()=>{const d=Object.fromEntries(new FormData(form));d.active=form.elements.active.checked;d.daily_limit=Number(d.daily_limit);await api('/accounts/'+form.dataset.editBot,'PATCH',d);await render();message('계정 설정을 저장했어요.');});});
   all('[data-image-bot]').forEach(input=>input.onchange=()=>action(async()=>{if(!input.files[0])return;const r=await api('/assets','POST',await optimize(input.files[0]));await api('/accounts/'+input.dataset.imageBot+'/image','PUT',{sha:r.sha});await render();message('프로필 이미지를 변경했어요.');}));
  }else if(tab==='settings'){
   const d=await api('/settings');config=d.config;revision=d.revision;
   const nums={comments:['작품당 댓글 수',0,2],probability:['댓글 작성 확률 (%)',0,100],giftMin:['응원별 최소 수량',1,20],giftMax:['응원별 최대 수량',1,20],commentMin:['댓글 최소 지연 (초)',0,86400],commentMax:['댓글 최대 지연 (초)',0,86400],giftDelayMin:['선물 최소 지연 (초)',0,86400],giftDelayMax:['선물 최대 지연 (초)',0,86400],dailyComments:['하루 댓글 한도',0,10000],dailyGifts:['하루 응원별 한도',0,20000],creatorDaily:['창작자당 하루 지원 작품 수',0,20],humanThreshold:['생략할 실제 회원 반응 수',1,100]};
   panel.innerHTML=`<form data-bot-settings class="admin-card"><h2>자동화 · 댓글 · 무료 응원별</h2><p>전체 ON은 실제 회원 작품에 대한 자동 활동을 시작합니다. 검증 및 운영자 승인 후 사용하세요.</p><div class="bot-form-grid">${Object.entries({enabled:'전체 자동 활동 ON',gifts:'공식 AI 응원별 ON',newOnly:'첫 작품만 응원 (해제하면 기존 회원도 지원)',newPriority:'신규 회원 우선 응원'}).map(([k,n])=>`<label><input name="${k}" type="checkbox" ${config[k]?'checked':''}> ${n}</label>`).join('')}${Object.entries(nums).map(([k,[n,min,max]])=>label(n,`<input name="${k}" type="number" min="${min}" max="${max}" value="${config[k]}" required>`)).join('')}</div><fieldset><legend>대상 작품</legend>${['original','solo','duet','dubbing'].map(k=>`<label><input name="kind" value="${k}" type="checkbox" ${config.kinds.includes(k)?'checked':''}> ${categories[k]}</label>`).join('')}</fieldset><button class="primary-button">설정 저장</button></form>`;
   q('[data-bot-settings]').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;action(async()=>{const d=new FormData(f),next={...config};for(const k of Object.keys(nums))next[k]=Number(d.get(k));for(const k of ['enabled','gifts','newOnly','newPriority'])next[k]=f.elements[k].checked;next.kinds=d.getAll('kind');await api('/settings','PUT',{config:next,revision});await render();message('설정을 저장했어요.');});};
  }else if(tab==='templates'){
   const d=await api('/templates');panel.innerHTML=`<p>음원 분석 없이 사용하는 ${d.templates.length}개 템플릿입니다. 실제 감상한 것처럼 표현하지 마세요.</p><form data-template-add class="admin-card bot-form-grid">${label('분류',`<select name="category">${options(categories,'general')}</select>`)}${label('말투',`<select name="style">${options(styles,'warm')}</select>`)}${label('댓글 문구','<textarea name="body" maxlength="300" required></textarea>')}<button class="primary-button">템플릿 추가</button></form><label>분류별 보기<select data-category-filter><option value="all">전체</option>${options(categories,'')}</select></label><div data-template-list>${d.templates.map(t=>`<details class="management-card" data-category="${t.category}"><summary>${esc(categories[t.category])} · ${esc(t.body)}</summary><form data-template-edit="${t.id}">${label('문구',`<textarea name="body" maxlength="300" required>${esc(t.body)}</textarea>`)}${label('분류',`<select name="category">${options(categories,t.category)}</select>`)}${label('말투',`<select name="style">${options(styles,t.style)}</select>`)}<label><input name="active" type="checkbox" ${t.active?'checked':''}> 사용</label><button class="primary-button">저장</button><button type="button" class="small-button" data-template-delete="${t.id}">삭제</button></form></details>`).join('')}</div>`;
   q('[data-category-filter]').onchange=e=>all('[data-category]').forEach(el=>el.hidden=e.target.value!=='all'&&el.dataset.category!==e.target.value);
   q('[data-template-add]').onsubmit=e=>{e.preventDefault();action(async()=>{await api('/templates','POST',Object.fromEntries(new FormData(e.target)));await render();message('템플릿을 추가했어요.');});};all('[data-template-edit]').forEach(f=>f.onsubmit=e=>{e.preventDefault();action(async()=>{await api('/templates/'+f.dataset.templateEdit,'PATCH',{...Object.fromEntries(new FormData(f)),active:f.elements.active.checked});await render();message('템플릿을 수정했어요.');});});all('[data-template-delete]').forEach(b=>b.onclick=()=>action(async()=>{await api('/templates/'+b.dataset.templateDelete,'DELETE');await render();message('템플릿을 삭제했어요. 활동 기록은 보존됩니다.');}));
  }else if(tab==='activities'){
   const d=await api('/activities?offset='+recordOffset);panel.innerHTML=`<h2>댓글 · 선물 실행 내역</h2><div class="bot-records">${d.activities.map(a=>`<article class="management-card"><strong>${esc(a.name)} <span class="ai-account-badge">AI</span></strong><p>${esc(a.body||'공식 응원별 ×'+a.quantity)}</p><a href="/#${a.target_type==='track'?'song':'dubbing'}/${esc(a.target_id)}">${esc(a.target_id)}</a><small>${date(a.created)} · 성공</small></article>`).join('')||'<p>활동 기록이 없어요.</p>'}</div><h2>대기 · 생략 · 실패</h2>${d.jobs.map(j=>`<article class="management-card"><strong>${esc(j.target_id)} · ${esc(j.action)} · ${esc(j.state)}</strong><p>${esc(j.error)}</p><small>예약 ${date(j.due)} · 시도 ${j.attempts}회</small>${j.state==='failed'?`<button class="small-button" data-retry-job="${esc(j.id)}">재시도 예약</button>`:''}</article>`).join('')}<details><summary>관리자 감사 기록</summary>${d.audit.map(a=>`<details><summary>${esc(a.actor)} · ${esc(a.action)} · ${date(a.created)}</summary><pre class="bot-audit-details">${esc(a.details)}</pre></details>`).join('')}</details><div class="bot-inline"><button class="small-button" data-record-prev ${recordOffset===0?'disabled':''}>이전 기록</button><button class="small-button" data-record-next ${Math.max(d.activities.length,d.audit.length,d.jobs.length)<50?'disabled':''}>다음 기록</button></div>`;q('[data-record-prev]').onclick=()=>{recordOffset=Math.max(0,recordOffset-50);render();};q('[data-record-next]').onclick=()=>{recordOffset+=50;render();};all('[data-retry-job]').forEach(b=>b.onclick=()=>action(async()=>{await api('/retry','POST',{id:b.dataset.retryJob});await render();message('재시도를 예약했어요.');}));
  }else await importPage(panel);
 }catch(e){panel.innerHTML='<p>불러오지 못했어요.</p>';message(e.message);}}

 async function optimize(file){const bitmap=await createImageBitmap(file);try{const canvas=document.createElement('canvas');canvas.width=canvas.height=512;const ctx=canvas.getContext('2d'),size=Math.min(bitmap.width,bitmap.height);ctx.drawImage(bitmap,(bitmap.width-size)/2,(bitmap.height-size)/2,size,size,0,0,512,512);return await new Promise((ok,fail)=>canvas.toBlob(b=>b?ok(b):fail(new Error('사진 변환에 실패했어요.')),'image/webp',.85));}finally{bitmap.close();}}
 async function catalogueImage(item){
  if(!/^\/assets\/ai-bot-import\/[a-f0-9]{64}\.webp$/.test(item.image))throw new Error('허용된 사이그램 이미지가 아닙니다.');
  const r=await fetch(item.image);if(!r.ok)throw new Error('이미지를 불러오지 못했어요.');
  // Sites may serve WebP as octet-stream. Keep bytes intact; the upload API
  // still validates RIFF/WEBP signatures, size and operator authorization.
  return new Blob([await r.arrayBuffer()],{type:'image/webp'});
 }
 function parseCSV(text){const rows=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++;}else quote=!quote;}else if(!quote&&(c===','||c==='\n')){row.push(cell.trim());cell='';if(c==='\n'){if(row.some(Boolean))rows.push(row);row=[];}}else if(c!=='\r')cell+=c;}if(quote)throw new Error('CSV 따옴표를 확인해주세요.');row.push(cell.trim());if(row.some(Boolean))rows.push(row);const headers=(rows.shift()||[]).map(s=>s.replace(/^\uFEFF/,''));return rows.map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]||''])));}
 async function importPage(panel){
  panel.innerHTML=`<h2>사이그램 AI 캐릭터 · 이미지 일괄 등록</h2><p>일반 회원 사진을 가져오지 않습니다. 미리보기에서 선택한 항목만 비활성 서비스 계정으로 등록합니다.</p><div class="bot-inline"><button class="small-button" data-saigram-load>사이그램 캐릭터 목록</button><button class="small-button" data-import-all>등록 가능한 항목 전체 선택</button></div><form data-import-form class="admin-card">${label('프로필 이미지 여러 개 선택','<input name="images" type="file" multiple accept="image/jpeg,image/png,image/webp">')}${label('이름 매핑 CSV (선택)','<input name="csv" type="file" accept=".csv,text/csv">')}<p>CSV 열: source_key,name,image (이미지 파일명). CSV가 없으면 파일명을 닉네임으로 사용합니다.</p><button class="small-button">업로드 이미지 미리보기</button></form><label><input type="checkbox" data-owned-ai> 운영자 소유이며 재사용 권한이 확인된 AI 캐릭터 이미지입니다.</label><div data-import-preview class="bot-account-grid"></div><button class="primary-button" data-import-execute>선택 항목 검토 후 등록</button><p data-import-progress role="status"></p>`;
  const paint=()=>{q('[data-import-preview]').innerHTML=items.map((it,i)=>`<article class="management-card bot-account"><label><input type="checkbox" data-import-index="${i}" ${selected.has(i)?'checked':''} ${['duplicate','created'].includes(it.status)?'disabled':''}> ${esc(it.name)}</label>${it.image?`<img loading="lazy" decoding="async" src="${esc(it.image)}" alt="${esc(it.name)}">`:''}<small>${esc(it.source_key)}</small><p>${esc(it.error||it.status||'미등록')}</p></article>`).join('');all('[data-import-index]').forEach(box=>box.onchange=()=>box.checked?selected.add(Number(box.dataset.importIndex)):selected.delete(Number(box.dataset.importIndex)));};
  q('[data-saigram-load]').onclick=()=>action(async()=>{const r=await fetch('/assets/ai-bot-import/catalog.json');if(!r.ok)throw new Error('사이그램 검증 목록이 아직 준비되지 않았어요.');const catalog=await r.json();items=catalog.items;selected=new Set();paint();message('사이그램 소스 스냅샷 '+catalog.source_commit.slice(0,8)+' · '+items.length+'개 후보. 이미 등록된 항목은 실행 전 제외합니다.');});
  q('[data-import-all]').onclick=()=>{items.forEach((it,i)=>{if(!['duplicate','failed','created'].includes(it.status))selected.add(i);});paint();};
  q('[data-import-form]').onsubmit=e=>{e.preventDefault();const form=e.target;action(async()=>{const files=[...form.elements.images.files];if(files.length>500)throw new Error('한 번에 500개 이하로 선택해주세요.');const mapping=form.elements.csv.files[0]?parseCSV(await form.elements.csv.files[0].text()):files.map(f=>({source_key:'upload:'+f.name,name:f.name.replace(/\.[^.]+$/,''),image:f.name}));items=mapping.map(m=>{const file=files.find(f=>f.name===m.image);return {...m,source_key:m.source_key||'upload:'+m.image,file,image:file?URL.createObjectURL(file):'',status:file?'ready':'failed',error:file?'':'매핑한 이미지 파일이 없습니다.'};});selected=new Set();paint();});};
  const execute=q('[data-import-execute]');execute.textContent='선택 항목 서버 미리보기';
  const commit=document.createElement('button');commit.type='button';commit.className='primary-button';commit.textContent='검토한 계정 등록';commit.hidden=true;execute.after(commit);
  execute.onclick=()=>action(async()=>{
   if(!q('[data-owned-ai]').checked)throw new Error('운영자 소유 AI 이미지 사용 권한을 확인해주세요.');
   const chosen=[...selected].map(i=>items[i]);if(!chosen.length)throw new Error('등록할 항목을 선택해주세요.');
   reviewed=[];commit.hidden=true;const progress=q('[data-import-progress]');let done=0;
   for(let start=0;start<chosen.length;start+=5){const group=chosen.slice(start,start+5),ready=[];
    for(const item of group){try{progress.textContent=`${done+ready.length+1} / ${chosen.length} 이미지 확인 중`;
     const blob=item.file?await optimize(item.file):await catalogueImage(item);
     const staged=await api('/assets','POST',blob);item.sha=staged.sha;ready.push({name:item.name,source_key:item.source_key,sha:item.sha});
    }catch(e){item.status='failed';item.error=e.message;}}
    if(ready.length){const preview=await api('/import/preview','POST',{items:ready,owned_ai:true});for(const r of preview.items){const item=group.find(i=>i.source_key===r.source_key);if(item)Object.assign(item,r);}reviewed.push({items:ready,owned_ai:true,preview_token:preview.preview_token});}
    done+=group.length;progress.textContent=`${done} / ${chosen.length}개 확인 완료`;paint();
   }commit.hidden=!reviewed.length;message('서버 미리보기 완료. 중복·실패 항목을 확인하고 등록 버튼을 누르면 계정이 생성됩니다. 아직 계정은 등록하지 않았어요.');
  });
  commit.onclick=()=>action(async()=>{
   if(!q('[data-owned-ai]').checked)throw new Error('AI 이미지 사용 권한을 확인해주세요.');
   const progress=q('[data-import-progress]');let count=0;
   for(const group of reviewed){const result=await api('/import/execute','POST',group);for(const row of result.results){const item=items.find(i=>i.source_key===row.source_key);if(item)Object.assign(item,row);if(row.status==='created')count++;}paint();}
   selected=new Set();reviewed=[];commit.hidden=true;progress.textContent=count+'개 계정을 등록했어요. 실패한 항목은 다시 선택해 확인할 수 있어요.';message('새 계정은 비활성 상태이며 전체 자동 활동도 자동으로 켜지지 않습니다.');
  });paint();
 }
 document.addEventListener('aifect-admin-ai-bots',()=>render());
})();
